arguments.command:
cd /dateutil && python -c "
from dateutil.relativedelta import relativedelta
from datetime import datetime
try:
    print(datetime(2000,1,1) + relativedelta(months=1.0))
except Exception as e:
    print('ERR', type(e).__name__, e)
try:
    print(datetime(2000,1,1) + relativedelta(years=1.0))
except Exception as e:
    print('ERR', type(e).__name__, e)
"
